-- Pandoc filter for files generated by scripts/report.py, which may not exist
-- yet when the experiments that produce them have not run:
--
--   ```{.include file="build/tab_bench.md"}
--   ```
--     is replaced by the file's Markdown, or by a "pending" note.
--   ![caption](build/fig.pdf)
--     is replaced by a "pending" note when the image does not exist.

local function exists(path)
  local f = io.open(path, "r")
  if f then f:close() end
  return f ~= nil
end

local function pending(what)
  return pandoc.Para({pandoc.Strong("[Pendente]"), pandoc.Space(),
                      pandoc.Str(what .. " — aguardando os resultados de ada-scaling.sh.")})
end

function CodeBlock(el)
  if not el.classes:includes("include") then return nil end
  local path = el.attributes.file
  if not exists(path) then return pending("Tabela " .. path) end
  local f = io.open(path, "r")
  local doc = pandoc.read(f:read("a"), "markdown", {columns = 1000})
  f:close()
  return doc.blocks
end

function Figure(el)
  local missing = nil
  el:walk({Image = function(img)
    if not exists(img.src) then missing = img.src end
  end})
  if missing then return pending("Figura " .. missing) end
end
